import {runeRing,castFlash,RUNE_FORWARD} from './casting-feedback.mjs?v=forward-glow-1';
import * as T from './three.module.js';
export const ICE_HIT_RADIUS=.55;
export const ICE_BASIC={left:{name:'얼음탄',damage:7,cost:4,cooldown:.8,windup:.18,lock:.3,range:7,speed:13},right:{name:'얼음안개',damage:2,cost:7,cooldown:2.4,windup:0,lock:1.2,range:2.6,life:1.2,interval:.2}};
export class IceBasic{
 constructor(api){this.a=api;this.effects=[];}
 origin(owner,dir,hand){const side=0;const p=new T.Vector3(owner.x+dir.x*.72+dir.z*.24*side,1.42,owner.z+dir.z*.72-dir.x*.24*side);if(!this.a.clearPath(owner,p))p.set(owner.x,1.42,owner.z);return p;}
 pose(owner){return this.effects.filter(e=>e.type==='iceHandRing'&&e.owner===owner).map(e=>({hand:e.hand,dir:e.dir,reach:.6,height:1.42,weight:Math.min(1,(e.max-e.life)/.14,e.life/.12)}));}
 syncHands(owner,puppet){for(const e of this.effects){if(e.owner!==owner||!['iceHandRing','iceMist','castFlash'].includes(e.type))continue;const hand=e.hand||'right',bone=puppet?.lastPositions?.[hand==='left'?'LeftHand':'RightHand'];if(!bone)continue;const left=puppet?.lastPositions?.LeftHand,right=puppet?.lastPositions?.RightHand;const p=hand==='right'&&left&&right?left.clone().add(right).multiplyScalar(.5).addScaledVector(e.dir,RUNE_FORWARD):bone.clone().addScaledVector(e.dir,RUNE_FORWARD);e.mesh.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),e.dir);if(e.type==='iceMist')e.mesh.position.set(p.x,p.y-1.05,p.z);else e.mesh.position.copy(p);}}


 cast(owner,dir,hand,target=null,rangeScale=1,prepared=false,emission=null){const spec=ICE_BASIC[hand],side=hand==='left'?-1:1;owner.iceCastLock=Math.max(owner.iceCastLock||0,spec.lock);let origin=emission?.clone()||this.origin(owner,dir,hand);const ring=runeRing();ring.scale.setScalar(.14);for(const m of ring.children)m.material.color.set(0x62caff);ring.children.at(-1).material.color.set(0xd7f6ff);const glow=castFlash('#62caff',1);glow.children[0].visible=glow.children[1].visible=false;glow.children[2].material.opacity=glow.children[2].material.userData.opacity=.24;glow.children[3].intensity=glow.children[3].userData.intensity=4.5;glow.scale.setScalar(.8/.14);ring.add(glow);ring.position.copy(origin);ring.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),new T.Vector3(dir.x,0,dir.z));this.a.scene.add(ring);const life=hand==='right'?spec.life:.48;this.effects.push({type:'iceHandRing',mesh:ring,owner,hand,dir:dir.clone(),life,max:life});
 if(spec.windup&&!prepared){const mesh=new T.Group();mesh.position.copy(origin);this.effects.push({type:'iceWindup',mesh,owner,hand,rangeScale,origin:origin.clone(),target:target?new T.Vector3(target.x,0,target.z):null,dir:dir.clone(),life:spec.windup});}else this.emit(owner,dir,hand,origin,null,rangeScale);
 }
 emit(owner,dir,hand,origin,target=null,rangeScale=1){const spec=ICE_BASIC[hand],travel=spec.range*rangeScale;for(const ring of this.effects){if(ring.type==='iceHandRing'&&ring.owner===owner&&ring.hand===hand&&!ring.emitted){ring.emitted=true;ring.mesh.position.copy(origin);}}dir=new T.Vector3(dir.x,0,dir.z).normalize();
 const flash=castFlash('#62caff',1);flash.position.copy(origin);flash.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),dir);this.a.scene.add(flash);this.effects.push({type:'castFlash',mesh:flash,owner,hand,dir:dir.clone(),life:.22,max:.22});if(hand==='left'){const mesh=new T.Mesh(new T.OctahedronGeometry(.16,0),new T.MeshStandardMaterial({color:0x8edcff,emissive:0x1874bb,emissiveIntensity:.7,roughness:.2}));mesh.position.copy(origin);mesh.scale.set(.7,.7,2);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),dir);this.a.scene.add(mesh);this.effects.push({type:'shot',mesh,owner,dir:dir.clone(),speed:spec.speed,life:travel/spec.speed,damage:spec.damage});}
 else{const mesh=new T.Group();for(let j=0;j<64;j++){const shard=j>=40,puff=new T.Mesh(shard?new T.OctahedronGeometry(.055,0):new T.SphereGeometry(1,8,6),new T.MeshBasicMaterial({color:shard?0xd9f7ff:j%3?0x6dcaff:0xe0f8ff,transparent:true,opacity:0,depthWrite:false,blending:shard?T.AdditiveBlending:T.NormalBlending}));puff.userData={shard,seed:j*.618,angle:Math.sin(j*2.4)*.69};mesh.add(puff);}mesh.position.set(origin.x,0,origin.z);mesh.rotation.y=Math.atan2(dir.x,dir.z);this.a.scene.add(mesh);this.effects.push({type:'iceMist',mesh,owner,dir:dir.clone(),point:{x:origin.x,z:origin.z},range:spec.range*rangeScale,rangeScale,life:spec.life,max:spec.life,tick:0});}}
 update(dt){for(let i=this.effects.length-1;i>=0;i--){const e=this.effects[i];e.life-=dt;let done=e.life<=0;
 if(e.type==='castFlash'){const fade=Math.max(0,e.life/e.max);e.mesh.scale.setScalar(1+(1-fade)*.7);e.mesh.traverse(m=>{if(m.material)m.material.opacity=m.material.userData.opacity*fade;if(m.isPointLight)m.intensity=m.userData.intensity*fade;});}
 if(e.type==='iceHandRing'){const fade=Math.min(1,Math.max(0,e.life/.15));e.mesh.traverse(m=>{if(m.material)m.material.opacity=m.material.userData.opacity*fade;if(m.isPointLight)m.intensity=(m.userData.intensity||1.8)*fade;});e.mesh.scale.setScalar(.14*(1+(1-e.life/e.max)*.15));}
 if(e.type==='iceWindup'&&done&&e.owner.hp>0)this.emit(e.owner,e.dir,e.hand,e.origin,e.target,e.rangeScale);
 if(e.type==='shot'){const expired=done,travelDt=Math.min(dt,Math.max(0,e.life+dt));done=false;const steps=Math.max(1,Math.ceil(e.speed*travelDt/.08));for(let j=0;j<steps&&!done;j++){const before=e.mesh.position.clone(),next=before.clone().addScaledVector(e.dir,e.speed*travelDt/steps);if(this.a.collides(next.x,next.z,.12)||!this.a.clearPath(before,next)){done=true;break;}e.mesh.position.copy(next);const target=this.a.targets(e.owner).find(t=>this.a.screenHit?this.a.screenHit(e,before,next,t):Math.hypot(t.x-next.x,t.z-next.z)<ICE_HIT_RADIUS);if(target){if(this.a.hit(target,e.damage,e.dir,0,e.owner))target.slow=Math.max(target.slow||0,1.2);done=true;}}done=done||expired;}
 if(e.type==='iceMist'){e.tick-=dt;const age=e.max-e.life,fade=Math.min(1,e.life/.3);for(const p of e.mesh.children){const u=p.userData;if(u.halo){p.material.opacity=.8*fade;p.rotation.z=age*2;continue;}const phase=(age*(u.shard?1.8:1.15)+u.seed)%1,travel=.15+phase*2.3*(e.rangeScale||1),width=.08+phase*.35;p.position.set(Math.sin(u.angle)*travel+Math.sin(age*8+u.seed)*width*.2,1.05-phase*.45+Math.sin(u.seed*5+age*4)*.13,Math.cos(u.angle)*travel);if(u.shard){p.scale.set(.6,1.8+phase, .6);p.rotation.set(age*3+u.seed,age*2,u.seed);p.material.opacity=Math.sin(phase*Math.PI)*fade*.95;}else{const size=.12+phase*.4;p.scale.set(size*(1+phase*.45),size*.7,size);p.material.opacity=Math.sin(phase*Math.PI)*fade*.33;}}if(!done&&e.tick<=0){e.tick+=.2;for(const t of this.a.targets(e.owner)){const dx=t.x-e.point.x,dz=t.z-e.point.z,d=Math.hypot(dx,dz);if(!(this.a.areaHit?this.a.areaHit(t,e.point,e.range||2.6,e.dir,true):d<=(e.range||2.6)&&(d<.01||(dx*e.dir.x+dz*e.dir.z)/d>=.65))||!this.a.clearPath(e.point,t))continue;if(this.a.hit(t,2,e.dir,0,e.owner))t.slow=Math.max(t.slow||0,.8);}}}
 if(done){this.a.remove(e.mesh);this.effects.splice(i,1);}}}
 clear(){for(const e of this.effects)this.a.remove(e.mesh);this.effects=[];}
}
